use super::kit::*;
pub fn commands()->Vec<Command>{vec![Command{name:"add_acescct_primaries",description:"Add boundAP1linear nativeOCIOACEScct lift/gamma/gain/offset effect. ExplicitKimo formula, notResolvewheelparity. Declared configspaces required; no projectdefault changes.",mutates:true,
schema:obj(vec![("clip_id",s("clip")),("config_path",s("self-containedOCIOconfig")),("linear_space",s("AP1/D60linear configspace")),("cct_space",s("ACEScct/AP1 configspace")),("params",json!({"type":"object"}))],&["clip_id","config_path","linear_space","cct_space"]),run:|ss,a|{
 if !ss.project.color_pipeline.enabled||ss.project.color_pipeline.working_gamut!=3{return Err("requiresmanagedAP1working_gamut3".into())}
 let id=str_arg(a,"clip_id")?;if ss.project.find_clip(id).is_none(){return Err("no clip".into())}let mut pr=crate::effects::Params::new();if let Some(v)=a.get("params"){let o=v.as_object().ok_or("paramsobject required")?;for(k,v)in o{if !["lift_r","lift_g","lift_b","gamma_r","gamma_g","gamma_b","gain_r","gain_g","gain_b","offset_r","offset_g","offset_b","inverse"].contains(&k.as_str()){return Err(format!("unknownparam{k}"))}let n=v.as_f64().filter(|v|v.is_finite()).ok_or("finitenumericparams required")?;pr.insert(k.clone(),crate::keyframe::Prop::new(n));}}pr.insert("gamut".into(),crate::keyframe::Prop::new(3.));let mut strings=std::collections::BTreeMap::new();for k in ["config_path","linear_space","cct_space"]{strings.insert(k.into(),str_arg(a,k)?.into());}strings.insert("bound_linear_gamut".into(),"3".into());let mut test=crate::effects::Frame{w:1,h:1,d:vec![0.18,0.18,0.18,1.]};crate::color::cct_grade::apply(&pr,&strings,&mut test,0.)?;
 let clip_id=id.to_string();let fx=ss.project.gen_id("fx");ss.project.find_clip_mut(&clip_id).unwrap().effects.push(crate::model::Effect{id:fx.clone(),kind:"acescct_primaries".into(),params:pr,strings});Ok(json!({"effect_id":fx,"working_gamut":3,"formula":"signedpow(x+lift*(1-x),1/gamma)*gain+offset inACEScct","inverse":"(signedpow((y-offset)/gain,gamma)-lift)/(1-lift)","declared_spaces":true}))
}}]}
